// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/reminders", wrapper.ListReminders)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/reminders", wrapper.CreateReminder)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/reminders/{reminderId}", wrapper.DeleteReminder)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/reminders/{reminderId}", wrapper.GetReminder)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/reminders/{reminderId}", wrapper.UpdateReminder)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/reminders/{reminderId}/done", wrapper.CompleteReminder)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/reminders/{reminderId}/snooze", wrapper.SnoozeReminder)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notify/channels", wrapper.ListNotifyChannels)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notify/channels/{channel}", wrapper.GetNotifyChannel)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/notify/channels/{channel}", wrapper.UpdateNotifyChannel)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/notify/channels/{channel}/test", wrapper.TestNotifyChannel)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notify/routes", wrapper.ListNotifyRoutes)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/notify/routes", wrapper.ReplaceNotifyRoutes)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notify/quiet-hours", wrapper.GetQuietHours)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/notify/quiet-hours", wrapper.UpdateQuietHours)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/notify/actions", wrapper.RunNotifyAction)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notify/webpush/vapid-public-key", wrapper.GetVapidPublicKey)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/notify/webpush/subscriptions", wrapper.DeletePushSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/notify/webpush/subscriptions", wrapper.ListPushSubscriptions)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/notify/webpush/subscriptions", wrapper.AddPushSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/notify/webpush/subscriptions/{subscriptionId}", wrapper.DeletePushSubscriptionById)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/notify/webpush/test", wrapper.TestWebPush)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/notify/telegram/register-webhook", wrapper.RegisterTelegramWebhook)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/integrations/telegram/webhook", wrapper.TelegramWebhook)
	})

	return r
}
